      const todosPath = `/Users/agents/.claude/todos/${sessionId}.json`;
      try {
        await stat(todosPath);
        await unlink(todosPath);
        app.log.info(`Arquivo de todos também foi excluído: ${todosPath}`);
      } catch {
        // Arquivo de todos não existe, não faz nada
      }

