  app.delete('/api/documents/:sessionId', {
    schema: {
      params: z.object({
        sessionId: z.string()
      })
    }
  }, async (request, reply) => {
    try {
      const { sessionId } = request.params;
      const filePath = join(PROJECTS_DIR, `${sessionId}.jsonl`);

      // Verificar se o arquivo existe
      await stat(filePath);

