                className="text-xs bg-gray-100 text-gray-700 px-2 py-1 rounded font-mono flex items-center gap-1" 
                title={session.customName ? `ID: ${session.sessionId}` : "ID da sessão"}
              >
                {session.customName || session.sessionId.slice(0, 6)}
                {hoveredCard && (
