                    }}
                    className="text-gray-400 hover:text-gray-600 ml-1"
                  >
                    ✏️
                  </button>
                )}
              </span>
            )}
          </div>
        </div>
      </div>

      <div className="space-y-3 mt-3">
        {/* Pendentes */}
        {session.pendingCount > 0 && (
